window.__votdWeek && window.__votdWeek({"week":"2029-01-08","reading":"Doctrine and Covenants 1","days":[{"d":"2029-01-08","ref":"D&C 1:1","b":"D&C","c":1,"v":1,"he":"שִׁמְעוּ עַם כְּנֵסִיָּתִי נְאֻם קוֹל הַשֹּׁכֵן בַּמָּרוֹם אֲשֶׁר עֵינָיו עַל כׇּל־אָדָם אָכֵן אָמֵן אֲנִי אֹמֵר שִׁמְעוּ עַם מֵרָחוֹק וְיֹשְׁבֵי אִיֵּי הַיָּם הַקְשִׁיבוּ יַחְדָּו׃","en":"Hearken, O ye people of my church, saith the voice of him who dwells on high, and whose eyes are upon all men; yea, verily I say: Hearken ye people from afar; and ye that are upon the islands of the sea, listen together."},{"d":"2029-01-09","ref":"D&C 1:3","b":"D&C","c":1,"v":3,"he":"וְהַסּוֹרְרִים יִדָּקְרוּ בְּמַכְאוֹב רָב כִּי עֲוֹנֹתֵיהֶם יִקָּרְאוּ עַל הַגַּגּוֹת וּמַעֲשֵׂיהֶם הַנִּסְתָּרִים יִגָּלוּ׃","en":"And the rebellious shall be pierced with much sorrow; for their iniquities shall be spoken upon the housetops, and their secret acts shall be revealed."},{"d":"2029-01-10","ref":"D&C 1:10","b":"D&C","c":1,"v":10,"he":"עַד הַיּוֹם אֲשֶׁר יָבֹא יְהוָה לְשַׁלֵּם לְאִישׁ כְּמַעֲשֵׂהוּ וּלְמֹד לְאִישׁ כַּמִּדָּה אֲשֶׁר מָדַד לְרֵעֵהוּ׃","en":"Unto the day when the Lord shall come to recompense unto every man according to his work, and measure to every man according to the measure which he has measured to his fellow man."},{"d":"2029-01-11","ref":"D&C 1:19","b":"D&C","c":1,"v":19,"he":"וְהַחַלָּשִׁים אֲשֶׁר בְּתֵבֵל יֵצְאוּ וְשִׁבְּרוּ אֶת־הַחֲזָקִים וְהָעֲצוּמִים לְמַעַן לֹא יִיעַץ אִישׁ אֶת־רֵעֵהוּ וְלֹא יִבְטַח בִּזְרוֹעַ בָּשָׂר׃","en":"The weak things of the world shall come forth and break down the mighty and strong ones, that man should not counsel his fellow man, neither trust in the arm of flesh—"},{"d":"2029-01-12","ref":"D&C 1:35","b":"D&C","c":1,"v":35,"he":"כִּי אֵינֶנִּי נֹשֵׂא פָנִים וְחָפַצְתִּי אֲשֶׁר יֵדְעוּ כׇל־אָדָם כִּי הַיּוֹם מְמַהֵר לָבֹא וְהָעֵת טֶרֶם בָּאָה אַךְ קְרוֹבָה הִיא אֲשֶׁר יֻקַּח הַשָּׁלוֹם מִן־הָאָרֶץ וְהַשָּׂטָן יִמְשֹׁל בְּמֶמְשַׁלְתּוֹ׃","en":"For I am no respecter of persons, and will that all men shall know that the day speedily cometh; the hour is not yet, but is nigh at hand, when peace shall be taken from the earth, and the devil shall have power over his own dominion."},{"d":"2029-01-13","ref":"D&C 1:37","b":"D&C","c":1,"v":37,"he":"דִּרְשׁוּ אֶת־הַמִּצְוֹת הָאֵלֶּה כִּי אֱמֶת וְנֶאֱמָנוֹת הֵנָּה וְהַנְּבוּאוֹת וּדְבָרַי הַטּוֹבִים אֲשֶׁר בָּהֶן כֻּלָּם יִמָּלְאוּ׃","en":"Search these commandments, for they are true and faithful, and the prophecies and promises which are in them shall all be fulfilled."},{"d":"2029-01-14","ref":"D&C 1:38","b":"D&C","c":1,"v":38,"he":"אֲשֶׁר דִּבַּרְתִּי אֲנִי יְהוָה דִּבַּרְתִּי וְלֹא אָשׁוּב מִדְּבָרִי וְאִם יַעַבְרוּ הַשָּׁמַיִם וְהָאָרֶץ דְּבָרִי לֹא יַעֲבֹר כִּי יִמָּלֵא הַכֹּל אִם בְּקוֹלִי אִם בְּקוֹל עֲבָדַי אֶחָד הוּא׃","en":"What I the Lord have spoken, I have spoken, and I excuse not myself; and though the heavens and the earth pass away, my word shall not pass away, but shall all be fulfilled, whether by mine own voice or by the voice of my servants, it is the same."}]});
